import csv,json,re,os,shutil,html,random
BASE=os.environ.get('BASE_PATH','/freshmillfinder/')
ROOT=os.path.dirname(os.path.abspath(__file__));OUT=os.path.join(ROOT,'_site')
SN={'AL':'Alabama','AK':'Alaska','AZ':'Arizona','AR':'Arkansas','CA':'California','CO':'Colorado','CT':'Connecticut','DE':'Delaware','DC':'Washington, D.C.','FL':'Florida','GA':'Georgia','HI':'Hawaii','ID':'Idaho','IL':'Illinois','IN':'Indiana','IA':'Iowa','KS':'Kansas','KY':'Kentucky','LA':'Louisiana','ME':'Maine','MD':'Maryland','MA':'Massachusetts','MI':'Michigan','MN':'Minnesota','MS':'Mississippi','MO':'Missouri','MT':'Montana','NE':'Nebraska','NV':'Nevada','NH':'New Hampshire','NJ':'New Jersey','NM':'New Mexico','NY':'New York','NC':'North Carolina','ND':'North Dakota','OH':'Ohio','OK':'Oklahoma','OR':'Oregon','PA':'Pennsylvania','RI':'Rhode Island','SC':'South Carolina','SD':'South Dakota','TN':'Tennessee','TX':'Texas','UT':'Utah','VT':'Vermont','VA':'Virginia','WA':'Washington','WV':'West Virginia','WI':'Wisconsin','WY':'Wyoming'}
# approximate geographic centroids (lat, lon)
CEN={'AL':(32.8,-86.8),'AK':(64.7,-152.3),'AZ':(34.3,-111.7),'AR':(34.9,-92.4),'CA':(37.2,-119.5),'CO':(39.0,-105.5),'CT':(41.6,-72.7),'DE':(39.0,-75.5),'DC':(38.9,-77.03),'FL':(28.6,-82.4),'GA':(32.7,-83.4),'HI':(20.3,-156.4),'ID':(44.4,-114.6),'IL':(40.0,-89.2),'IN':(39.9,-86.3),'IA':(42.1,-93.5),'KS':(38.5,-98.4),'KY':(37.5,-85.3),'LA':(31.1,-92.0),'ME':(45.4,-69.2),'MD':(39.0,-76.8),'MA':(42.3,-71.8),'MI':(44.3,-85.4),'MN':(46.3,-94.3),'MS':(32.7,-89.7),'MO':(38.4,-92.5),'MT':(47.0,-109.6),'NE':(41.5,-99.8),'NV':(39.3,-116.6),'NH':(43.7,-71.6),'NJ':(40.2,-74.7),'NM':(34.4,-106.1),'NY':(42.9,-75.5),'NC':(35.6,-79.4),'ND':(47.5,-100.5),'OH':(40.3,-82.8),'OK':(35.6,-97.5),'OR':(43.9,-120.6),'PA':(40.9,-77.8),'RI':(41.7,-71.5),'SC':(33.9,-80.9),'SD':(44.4,-100.2),'TN':(35.9,-86.4),'TX':(31.5,-99.3),'UT':(39.3,-111.7),'VT':(44.1,-72.7),'VA':(37.5,-78.9),'WA':(47.4,-120.5),'WV':(38.6,-80.6),'WI':(44.6,-89.9),'WY':(43.0,-107.6)}
GRAINS=[('Wheat',r'wheat|bread flour|pastry flour|all-purpose|hard red|soft white|hard white'),('Einkorn',r'einkorn'),('Emmer / Farro',r'emmer|farro'),('Spelt',r'spelt'),('Khorasan / Kamut',r'khorasan|kamut'),('Sonora wheat',r'sonora'),('Red Fife',r'red fife'),('Turkey Red',r'turkey red'),('Durum',r'durum'),('Rye',r'\brye'),('Buckwheat',r'buckwheat'),('Corn / Cornmeal',r'\bcorn\b|cornmeal|polenta|grits|masa|johnny'),('Oats',r'\boats?\b'),('Barley',r'barley'),('Rice',r'\brice'),('Sorghum',r'sorghum'),('Millet',r'millet'),('Teff',r'teff')]
esc=lambda s:html.escape(s or '')
slug=lambda s:re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
cache=json.load(open(os.path.join(ROOT,'..','raw','geocache.json'))) if os.path.exists(os.path.join(ROOT,'..','raw','geocache.json')) else {}
mills=[];used=set()
for r in csv.DictReader(open(os.path.join(ROOT,'..','mills.csv'))):
    s=slug(r['name']);s=s if s not in used else s+'-'+r['state'].lower();used.add(s)
    city=r['city'].split('(')[0].strip();ll=cache.get(f"{city}|{r['state']}");approx=False
    if not ll:
        c=CEN[r['state']];rnd=random.Random(s);ll=[c[0]+rnd.uniform(-.6,.6),c[1]+rnd.uniform(-.8,.8)];approx=True
    g=[n for n,p in GRAINS if re.search(p,r['grains_flours'],re.I)]
    host=re.sub(r'^https?://(www\.)?','',r['website_url']).split('/')[0]
    mills.append(dict(slug=s,name=r['name'],url=r['website_url'],host=host,city=city,state=r['state'],grains_raw=r['grains_flours'],grains=g,ships=r['ships']=='yes',shop=r['sells_retail_online']=='y',notes=r['notes'],source=r['source_url'],verified=r['last_verified'],lat=round(ll[0],4),lon=round(ll[1],4),approx=approx))
states=sorted({m['state'] for m in mills},key=lambda k:SN[k])
def page(path,title,body,desc='Find small and regional flour mills and stone-ground flours across the US.',depth=None,extra_head='',extra_js='',pre=None,fname='index.html'):
    d=path.count('/') if depth is None else depth;pre=pre or ('../'*d or './')
    nav=''.join(f'<a href="{pre}{h}">{t}</a>' for h,t in [('','Map'),('directory/','Directory'),('ships-nationwide/','Ships Nationwide'),('states/','States'),('for-mills/','For Mills'),('newsletter/','Newsletter')])
    h=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>🌾</text></svg>"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,800&family=Inter:wght@400;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="{pre}assets/style.css">{extra_head}</head><body>
<header class="top"><div class="wrap"><a class="brand" href="{pre}"><span>🌾</span> Fresh-Mill Finder</a><button class="menu" aria-label="Menu" onclick="document.body.classList.toggle('nav-open')">☰</button><nav>{nav}</nav></div></header>
<main class="wrap">{body}</main>
<footer><div class="wrap"><div><strong>Fresh-Mill Finder</strong> — a directory of small &amp; regional US flour mills.<br><small>Listings compiled from public sources; always confirm details with the mill. Some links on this site may be affiliate links — see our <a href="{pre}disclosure/">disclosure</a>.</small></div><div class="flinks"><a href="{pre}sources/">Sources &amp; methodology</a><a href="{pre}for-mills/">Claim / feature a listing</a><a href="{pre}newsletter/">Newsletter</a><a href="{pre}disclosure/">Affiliate disclosure</a><a href="{pre}privacy/">Privacy</a></div></div></footer>{extra_js}</body></html>'''
    p=os.path.join(OUT,path,fname);os.makedirs(os.path.dirname(p),exist_ok=True);open(p,'w').write(h)
def badges(m):
    b=''.join(f'<span class="tag">{esc(g)}</span>' for g in m['grains'][:6])
    if m['ships']:b='<span class="tag ship">📦 Ships</span>'+b
    if m['shop']:b='<span class="tag shop">🛒 Online shop</span>'+b
    return b
def card(m,pre):
    loc=', '.join(x for x in [m['city'],SN[m['state']]] if x)
    return f'<article class="card"><h3><a href="{pre}mill/{m["slug"]}/">{esc(m["name"])}</a></h3><p class="loc">📍 {esc(loc)}</p><div class="tags">{badges(m)}</div><p class="links"><a href="{esc(m["url"])}" rel="noopener" target="_blank">Visit {esc(m["host"])} ↗</a></p></article>'
if os.path.exists(OUT):shutil.rmtree(OUT)
os.makedirs(OUT+'/assets');shutil.copy(os.path.join(ROOT,'assets','style.css'),OUT+'/assets/');shutil.copy(os.path.join(ROOT,'assets','app.js'),OUT+'/assets/')
json.dump(dict(mills=mills,states={k:SN[k] for k in states},grains=[g for g,_ in GRAINS]),open(OUT+'/assets/mills.json','w'))
LH='<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css">'
LJ=lambda pre,mode:f'<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script><script>window.FMF={{base:"{pre}",mode:"{mode}"}}</script><script src="{pre}assets/app.js"></script>'
FILTERS='''<div class="filters"><input id="q" type="search" placeholder="Search mills, towns, grains…" aria-label="Search"><select id="state" aria-label="State"><option value="">All states</option></select><select id="grain" aria-label="Grain"><option value="">All grains</option></select><label class="chk"><input type="checkbox" id="ships"> Ships</label><label class="chk"><input type="checkbox" id="shop"> Online shop</label></div><p id="count" class="count"></p>'''
nship=sum(m['ships'] for m in mills)
SIGNUP=lambda pre:f'<form class="signup" onsubmit="event.preventDefault();this.innerHTML=\'<p>🍞 Thanks! Our newsletter is launching soon — signups aren\\\'t being collected yet.</p>\'"><label for="em">The Weekly Loaf — one mill spotlight, new listings &amp; a recipe every week.</label><div><input id="em" type="email" placeholder="you@example.com" required><button>Notify me</button></div><small>Placeholder — no email provider connected yet; nothing is stored.</small></form>'
page('','Fresh-Mill Finder — small & regional flour mills near you',f'''<section class="hero"><h1>Find fresh, stone-ground flour from mills near you.</h1><p>{len(mills)} small and regional mills, farms and milling bakeries across {len(states)} states — searchable by state, grain and who ships nationwide.</p></section>{FILTERS}<div id="map" class="map"></div><div id="list" class="grid"></div><section class="band">{SIGNUP('./')}</section>''',depth=0,extra_head=LH,extra_js=LJ('./','map'))
page('directory/','Directory — Fresh-Mill Finder',f'<h1>Mill directory</h1>{FILTERS}<div id="list" class="grid"></div>',extra_js=LJ('../','list'))
page('ships-nationwide/','Mills that ship nationwide — Fresh-Mill Finder',f'<h1>📦 Mills that ship</h1><p class="lead">{nship} mills where we saw shipping or mail-order info. Always check each mill\'s shipping area and rates — some ship only within the contiguous US or to certain regions.</p><div class="grid">'+''.join(card(m,'../') for m in sorted(mills,key=lambda m:m['name']) if m['ships'])+'</div>')
page('states/','Flour mills by state — Fresh-Mill Finder','<h1>Browse by state</h1><div class="states">'+''.join(f'<a href="../state/{k.lower()}/"><strong>{SN[k]}</strong><span>{sum(m["state"]==k for m in mills)} mills</span></a>' for k in states)+'</div>')
for k in states:
    ms=sorted([m for m in mills if m['state']==k],key=lambda m:m['name'])
    page(f'state/{k.lower()}/',f'Flour mills in {SN[k]} — Fresh-Mill Finder',f'<p class="crumb"><a href="../../states/">States</a> › {SN[k]}</p><h1>Flour mills in {SN[k]}</h1><p class="lead">{len(ms)} listed · {sum(m["ships"] for m in ms)} ship · {sum(m["shop"] for m in ms)} have an online shop</p><div class="grid">'+''.join(card(m,'../../') for m in ms)+'</div>',desc=f'Small and regional flour mills and stone-ground flour in {SN[k]}.')
for m in mills:
    loc=', '.join(x for x in [m['city'],SN[m['state']]] if x)
    yn=lambda v,t:('✅ '+t) if v else '— Not confirmed'
    srcs=''.join(f'<li><a href="{esc(u.split(" ")[0])}" rel="noopener" target="_blank">{esc(u)}</a></li>' for u in m['source'].split('; ') if u.startswith('http') or u.startswith('WebFetch'))
    body=f'''<p class="crumb"><a href="../../states/">States</a> › <a href="../../state/{m["state"].lower()}/">{SN[m["state"]]}</a> › {esc(m["name"])}</p><div class="detail"><div><h1>{esc(m["name"])}</h1><p class="loc">📍 {esc(loc)}</p><div class="tags">{badges(m)}</div>
<dl><dt>Grains &amp; flours</dt><dd>{esc(m["grains_raw"]) or '<em>Not yet recorded</em>'}</dd><dt>Ships</dt><dd>{yn(m["ships"],"Shipping / mail order seen")}</dd><dt>Online shop</dt><dd>{yn(m["shop"],"Online store detected")}</dd><dt>Notes</dt><dd>{esc(m["notes"]) or '—'}</dd><dt>Last verified</dt><dd>{esc(m["verified"])}</dd></dl>
<p><a class="btn" href="{esc(m["url"])}" rel="noopener" target="_blank">Visit {esc(m["host"])} ↗</a></p>
<details><summary>Sources</summary><ul>{srcs}</ul></details><p class="small">Is this your mill? <a href="../../for-mills/">Claim or correct this listing</a>.</p></div>
<div id="minimap" class="minimap" data-lat="{m["lat"]}" data-lon="{m["lon"]}" data-approx="{int(m["approx"])}"></div></div>'''
    page(f'mill/{m["slug"]}/',f'{m["name"]} — {SN[m["state"]]} flour mill | Fresh-Mill Finder',body,desc=f'{m["name"]} in {loc}: grains, flours, shipping and where to buy.',extra_head=LH,extra_js=LJ('../../','mini'))
page('for-mills/','For mills — claim or feature your listing','''<h1>For mills</h1><p class="lead">Run a mill, grain farm or milling bakery? Help bakers find you.</p><div class="grid two"><article class="card"><h3>Claim / correct your listing — free</h3><p>Update your grains, shipping status, photos and shop link. Every listing stays free.</p><button class="btn" disabled>Claim form coming soon</button></article><article class="card feature"><h3>⭐ Featured listing</h3><ul><li>Pinned to the top of your state page</li><li>Highlighted marker on the map</li><li>A spotlight in The Weekly Loaf newsletter</li></ul><p><strong>Pricing coming soon.</strong></p><button class="btn" disabled>Feature your mill — coming soon</button></article></div><p class="small">Placeholder: claim and feature forms aren't live yet. Featured placements will always be labeled.</p>''')
page('newsletter/','The Weekly Loaf newsletter — Fresh-Mill Finder','<h1>The Weekly Loaf</h1><p class="lead">A short weekly email: one mill spotlight, newly added listings, and a recipe that shows off fresh flour.</p>'+SIGNUP('../'))
page('disclosure/','Affiliate disclosure — Fresh-Mill Finder','<h1>Affiliate disclosure</h1><p>Fresh-Mill Finder is reader-supported. Some links on this site — for example to baking ingredients and equipment such as King Arthur Baking or Challenger Breadware — may be affiliate links. If you buy through them, we may earn a small commission at no extra cost to you.</p><p>Mill listings are not affiliate links, and inclusion in the directory is free. Paid “Featured” placements, when offered, will always be clearly labeled.</p><p>This disclosure is provided in line with the U.S. FTC’s Endorsement Guides.</p>')
page('privacy/','Privacy — Fresh-Mill Finder','<h1>Privacy</h1><p>This preview site sets no cookies and collects no personal information. The newsletter form is a placeholder and does not store anything. Map tiles are loaded from OpenStreetMap, and fonts and map scripts from public CDNs, which may see your IP address as part of normal web requests.</p>')
page('sources/','Sources & methodology — Fresh-Mill Finder',f'''<h1>Sources &amp; methodology</h1><p>Listings were compiled in October 2026 from public sources, and each mill’s website was fetched and confirmed to be live at the time of verification (see “last verified” on each listing).</p><ul class="srcs"><li><a href="https://wholegrainscouncil.org/find-whole-grains/local-grains">Whole Grains Council — Local Grains Map</a></li><li><a href="https://www.sourdoughgeeks.com/north-american-regional-grain-mills">Sourdough Geeks — North American Regional Grain Mills</a> (which compiles Wordloaf, Ritual Fine Foods, Amy Halloran, Grinder Finder and New American Stone Mills)</li><li><a href="https://amyhalloran.net/freshflour/">Amy Halloran — Fresh Flour Resources</a></li><li><a href="https://foodlab.nutrition.tufts.edu/resources/">Tufts Food Lab — Resources</a></li><li>Individual mill websites</li></ul><h2>What the fields mean</h2><ul><li><strong>Ships</strong> — we saw shipping or mail-order information (on the mill’s site or in the WGC map). Blank means unknown, not “no”.</li><li><strong>Online shop</strong> — an online store or cart was detected on the mill’s website.</li><li><strong>Map location</strong> — geocoded from city &amp; state using OpenStreetMap Nominatim; where the city is unknown, the pin is placed approximately within the state.</li></ul><p>Map data © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>. Spot an error? <a href="../for-mills/">Let us know</a>.</p>''')
urls=['','directory/','ships-nationwide/','states/','for-mills/','newsletter/','disclosure/','privacy/','sources/']+[f'state/{k.lower()}/' for k in states]+[f'mill/{m["slug"]}/' for m in mills]
open(OUT+'/sitemap.xml','w').write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://freshmillfinder.com/{u}</loc></url>' for u in urls)+'</urlset>')
open(OUT+'/robots.txt','w').write('User-agent: *\nAllow: /\n')
page('','Page not found — Fresh-Mill Finder',f'<h1>Page not found</h1><p class="lead">Sorry, that page has gone stale. Try the <a href="{BASE}">map</a>, the <a href="{BASE}directory/">directory</a> or <a href="{BASE}states/">browse by state</a>.</p>',pre=BASE,fname='404.html')
print('pages',len(urls),'approx pins',sum(m['approx'] for m in mills))
